<template><div><div class="page-head"><div><span>PHM INTEGRATION / COMPONENT ARCHIVE</span><h2>航天器部件档案</h2><p>统一浏览部件基础信息与寿命档案，共 {{rows.length}} 项。</p></div><el-button :loading="loading" @click="load">刷新数据</el-button></div><el-card shadow="never"><div class="toolbar"><el-input v-model="keyword" clearable placeholder="按编号或名称检索" style="width:280px"/><el-switch v-model="tableMode" active-text="表格视图"/></div><el-table v-if="tableMode" :data="filtered" stripe v-loading="loading" @row-click="show"><el-table-column prop="code" label="编号" width="150"/><el-table-column prop="name" label="名称"/><el-table-column prop="manufacturer" label="生产单位"/><el-table-column prop="flight_count" label="飞行次数" width="110"/><el-table-column label="操作" width="80"><template #default="s"><el-button link type="primary" @click.stop="show(s.row)">详情</el-button></template></el-table-column></el-table><div v-else class="cards"><el-card v-for="row in filtered" :key="row.code" shadow="hover" @click="show(row)"><div class="code">{{row.code}}</div><h3>{{row.name}}</h3><p>{{row.manufacturer||'生产单位未填写'}}</p><div class="foot"><span>已飞行次数</span><b>{{row.flight_count??'—'}}</b></div></el-card></div><el-empty v-if="!loading&&!filtered.length" description="暂无匹配部件"/></el-card><el-drawer v-model="open" :title="`${current.name||''} · ${current.code||''}`" size="520px"><el-skeleton v-if="detailLoading" :rows="5" animated/><el-descriptions v-else :column="1" border><el-descriptions-item v-for="x in detail.base_info||[]" :key="x.baseinfo||x.consumerinfo" :label="x.baseinfo||x.consumerinfo">{{x.attribute??x.attributevalue}}</el-descriptions-item></el-descriptions></el-drawer></div></template>
<script setup>import{ref,computed,onMounted}from'vue';import{ElMessage}from'element-plus';const rows=ref([]),keyword=ref(''),loading=ref(false),tableMode=ref(false),open=ref(false),current=ref({}),detail=ref({}),detailLoading=ref(false);const load=async()=>{loading.value=true;try{const r=await fetch('/api/v1/integrations/wujiaxin/components/');if(!r.ok)throw Error();rows.value=(await r.json()).results||[]}catch{ElMessage.error('部件档案加载失败')}finally{loading.value=false}};onMounted(load);const filtered=computed(()=>{const k=keyword.value.trim().toLowerCase();return rows.value.filter(r=>!k||`${r.code} ${r.name} ${r.manufacturer||''}`.toLowerCase().includes(k))});async function show(row){current.value=row;open.value=true;detailLoading.value=true;try{detail.value=await(await fetch(`/api/v1/integrations/wujiaxin/components/${row.code}/`)).json()}finally{detailLoading.value=false}}</script>
<style scoped>.page-head{display:flex;justify-content:space-between;align-items:end;margin-bottom:18px}.page-head span{font-size:11px;color:#2c82e7;font-weight:700}.page-head h2{margin:7px 0}.page-head p{margin:0;color:#8391a5}.toolbar{display:flex;gap:18px;align-items:center;margin-bottom:15px}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.el-card{border-radius:10px}.cards .el-card{cursor:pointer}.code{font-size:11px;color:#3788e5;font-weight:700}.cards h3{margin:10px 0 6px}.cards p{height:34px;color:#8a97a7;font-size:12px}.foot{border-top:1px solid #edf0f4;padding-top:12px;display:flex;justify-content:space-between;font-size:12px}.foot b{color:#1f77d5}@media(max-width:1200px){.cards{grid-template-columns:repeat(3,1fr)}}</style>
